class GardenFireflies{
 constructor(canvas,getReduced){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.getReduced=getReduced;this.active=false;this.time=0;this.blooms=[];this.hand=null;this.handAge=9;this.resize();this.createParticles();}
 particle(x=Math.random(),y=.18+Math.random()*.7,burst=false){const angle=Math.random()*Math.PI*2,speed=burst?.025+Math.random()*.045:.006+Math.random()*.012;return{x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed*.7,r:.7+Math.random()*1.8,phase:Math.random()*Math.PI*2,tone:Math.random()>.72?'#dfeeff':'#f6d38d',life:burst?4.5+Math.random()*3:Infinity,burst};}
 createParticles(){const count=matchMedia('(pointer:coarse)').matches?44:86;this.particles=Array.from({length:count},()=>this.particle());}
 resize(){const r=this.canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio,1.5);this.width=Math.max(1,r.width);this.height=Math.max(1,r.height);this.canvas.width=Math.round(this.width*ratio);this.canvas.height=Math.round(this.height*ratio);this.ctx.setTransform(ratio,0,0,ratio,0,0);}
 bloom(x,y){this.blooms.push({x,y,age:0});if(this.blooms.length>5)this.blooms.shift();const count=matchMedia('(pointer:coarse)').matches?12:22;for(let i=0;i<count;i++)this.particles.push(this.particle(x+(Math.random()-.5)*.04,y+(Math.random()-.5)*.035,true));if(this.particles.length>180)this.particles.splice(0,this.particles.length-180);}
 setHand(data){this.hand=data;this.handAge=0;}
 update(dt){if(!this.active)return;this.time+=dt;this.handAge+=dt;const c=this.ctx,w=this.width,h=this.height,reduced=this.getReduced();c.clearRect(0,0,w,h);const water=(this.time%5.2)/5.2;c.strokeStyle=`rgba(210,227,238,${(1-water)*.18})`;c.lineWidth=1;c.beginPath();c.ellipse(w*.66,h*.57,24+water*115,6+water*26,0,0,Math.PI*2);c.stroke();for(const bloom of this.blooms){bloom.age+=dt;const p=Math.min(1,bloom.age/2.8),radius=18+p*76;c.strokeStyle=`rgba(246,219,168,${(1-p)*.34})`;c.lineWidth=1;c.beginPath();c.arc(bloom.x*w,bloom.y*h,radius,0,Math.PI*2);c.stroke();for(let i=0;i<7;i++){const a=i*.897+bloom.age*.18,rr=10+p*(28+i*3);c.fillStyle=`rgba(255,241,207,${(1-p)*.42})`;c.beginPath();c.ellipse(bloom.x*w+Math.cos(a)*rr,bloom.y*h+Math.sin(a)*rr*.42,2.6,1.1,a,0,Math.PI*2);c.fill();}}
  this.blooms=this.blooms.filter(b=>b.age<2.8);const target=this.handAge<.45?this.hand:this.blooms.at(-1);for(const p of this.particles){if(!reduced){if(target){const dx=target.x-p.x,dy=target.y-p.y,d=Math.max(.04,Math.hypot(dx,dy)),force=this.handAge<.45?.016:.005;p.vx+=dx/d*dt*force;p.vy+=dy/d*dt*force*.76;}p.vx+=(Math.sin(this.time*.47+p.phase)*.00035)*dt;p.vy+=(Math.cos(this.time*.39+p.phase)*.00025)*dt;p.vx*=.988;p.vy*=.988;p.x+=p.vx;p.y+=p.vy;if(p.x<-.03)p.x=1.03;if(p.x>1.03)p.x=-.03;if(p.y<.12)p.y=.9;if(p.y>.94)p.y=.15;}if(Number.isFinite(p.life))p.life-=dt;const pulse=.55+.45*Math.sin(this.time*2.1+p.phase),fade=Number.isFinite(p.life)?Math.min(1,p.life):1;c.shadowBlur=7+p.r*3;c.shadowColor=p.tone;c.fillStyle=p.tone;c.globalAlpha=(.28+pulse*.58)*fade;c.beginPath();c.arc(p.x*w,p.y*h,p.r*(.7+pulse*.25),0,Math.PI*2);c.fill();}this.particles=this.particles.filter(p=>p.life>0);if(target&&this.handAge<.45){c.strokeStyle='rgba(245,225,182,.22)';c.beginPath();c.arc(target.x*w,target.y*h,18+Math.sin(this.time*3)*3,0,Math.PI*2);c.stroke();}c.globalAlpha=1;c.shadowBlur=0;}
 dispose(){this.active=false;this.blooms=[];}
}

export class MoonGardenExperience{
 constructor({getReduced,beforeOpen,onReturn,toggleHand,isHandActive,onStageReady,onBloom}){Object.assign(this,{getReduced,beforeOpen,onReturn,toggleHand,isHandActive,onStageReady,onBloom});this.active=false;this.busy=false;this.ticket=0;
  this.root=document.createElement('section');this.root.id='moon-garden';this.root.hidden=true;this.root.dataset.state='entry';this.root.innerHTML=`<div class="garden-stage"><img src="./assets/moonfirefly-court-v5.png" alt="月光下的玉兰花树、湖泊与镜面水池"><i class="garden-moonlight" aria-hidden="true"></i><i class="garden-flowerglow" aria-hidden="true"></i><canvas class="garden-fireflies" aria-label="轻点花园唤起更多流萤"></canvas><button class="garden-bloom-hint" type="button" aria-label="轻触花丛，唤起流萤"><i></i><i></i><i></i></button></div><div class="garden-entry"><div class="garden-entry-copy"><span>月色花房 · 隐藏庭院</span><h2>推开花房，<br>月光落满庭院。</h2><p>轻触花丛，让更多流萤从花影里飞出来。</p></div><button class="garden-enter">走进月华流萤庭 ↗</button></div><header class="garden-top"><span>月华流萤庭</span><nav><button class="garden-hand">✋ 开启手势</button><button class="garden-return">返回花房</button></nav></header><p class="garden-guide" role="status"></p>`;
  document.body.append(this.root);this.$=s=>this.root.querySelector(s);this.stage=this.$('.garden-stage');this.canvas=this.$('.garden-fireflies');this.effects=new GardenFireflies(this.canvas,this.getReduced);this.$('.garden-enter').onclick=()=>this.enter();this.$('.garden-bloom-hint').onclick=()=>this.release(.33,.34);this.$('.garden-return').onclick=()=>this.close();const handButton=this.$('.garden-hand');handButton.hidden=!this.toggleHand;handButton.onclick=async()=>{await this.toggleHand?.();this.setHandActive(this.isHandActive?.());};this.onPointer=e=>{if(this.root.dataset.state!=='view')return;const r=this.canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;this.release(x,y);};this.canvas.addEventListener('pointerdown',this.onPointer);this.onResize=()=>this.effects.resize();window.addEventListener('resize',this.onResize);
 }
 async open(){if(this.active)return;this.active=true;this.busy=true;this.touches=0;const ticket=++this.ticket;this.returnFocus=document.activeElement;this.root.hidden=false;this.root.dataset.state='entry';this.root.dataset.reduced=String(this.getReduced());this.$('.garden-entry').hidden=false;this.$('.garden-guide').textContent='';this.$('.garden-bloom-hint').classList.remove('is-used');this.effects.active=true;this.effects.resize();this.setHandActive(this.isHandActive?.());this.background=[...document.body.children].filter(el=>el!==this.root&&el.tagName!=='SCRIPT').map(el=>[el,el.inert]);this.background.forEach(([el])=>el.inert=true);document.body.classList.add('garden-active');this.$('.garden-return').focus();try{await Promise.all([this.$('.garden-stage img').decode(),Promise.resolve(this.beforeOpen?.())]);if(ticket!==this.ticket)return;this.background.forEach(([el])=>el.inert=true);await this.$('.garden-entry').animate([{opacity:0,transform:'translateX(-5%)'},{opacity:1,transform:'none'}],{duration:this.getReduced()?100:850,easing:'ease-out'}).finished;if(ticket===this.ticket){this.busy=false;this.$('.garden-enter').focus();}}catch(error){console.error('Moon garden failed to open',error);this.busy=false;this.$('.garden-entry-copy p').textContent='月下庭院暂时无法打开，请返回花房重试。';}}
 async enter(){if(this.busy||!this.active)return;this.busy=true;const ticket=this.ticket,entry=this.$('.garden-entry');this.$('.garden-enter').disabled=true;try{await entry.animate([{opacity:1,transform:'none'},{opacity:0,transform:'translateY(14px) scale(1.04)',filter:'blur(5px)'}],{duration:this.getReduced()?100:1050,easing:'cubic-bezier(.22,.7,.16,1)'}).finished;if(ticket!==this.ticket)return;entry.hidden=true;this.root.dataset.state='view';this.$('.garden-guide').textContent='轻触花丛，让流萤聚向月光。';this.$('.garden-return').focus();this.onStageReady?.();}finally{this.busy=false;this.$('.garden-enter').disabled=false;}}
 update(dt){if(this.active)this.effects.update(dt);}
 release(x,y){this.effects.bloom(x,y);this.$('.garden-bloom-hint').classList.add('is-used');this.onBloom?.();this.touches=(this.touches||0)+1;this.$('.garden-guide').textContent=this.touches>=3?'花丛里的流萤都醒来了，可以用手掌带它们飞行。':'更多流萤从花影里飞出来了。';}
 setHand(data){if(this.active&&this.root.dataset.state==='view')this.effects.setHand(data);}
 gestureBloom(x,y){if(this.active&&this.root.dataset.state==='view')this.release(x,y);}
 setHandActive(active){this.root.dataset.hand=String(Boolean(active));const button=this.$('.garden-hand');if(button)button.textContent=active?'✋ 手势引导中':'✋ 开启手势';}
 async close(){if(!this.active)return;++this.ticket;this.active=false;this.busy=false;this.effects.active=false;const a=this.root.animate([{opacity:1},{opacity:0}],{duration:this.getReduced()?100:350});try{await a.finished;}catch{}a.cancel();this.root.hidden=true;this.root.dataset.state='entry';this.$('.garden-entry').hidden=false;this.background?.forEach(([el,inert])=>el.inert=inert);document.body.classList.remove('garden-active');if(this.onReturn)await this.onReturn();else this.returnFocus?.focus({preventScroll:true});}
 dispose(){window.removeEventListener('resize',this.onResize);this.canvas.removeEventListener('pointerdown',this.onPointer);++this.ticket;this.effects.dispose();this.root.remove();}
}
